import {P} from './palette.js';
export function oval(c,x,y,rx,ry,color,outline=true){c.beginPath();c.ellipse(x,y,Math.max(.01,rx),Math.max(.01,ry),0,0,Math.PI*2);c.fillStyle=color;c.fill();if(outline){c.strokeStyle=P.ink;c.lineWidth=1.6;c.stroke()}}
export function line(c,points,color=P.ink,width=1.5){c.beginPath();c.moveTo(...points[0]);for(let i=1;i<points.length;i++)c.lineTo(...points[i]);c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.lineJoin='round';c.stroke()}
export function shape(c,points,color){c.beginPath();c.moveTo(...points[0]);for(let i=1;i<points.length;i++)c.lineTo(...points[i]);c.closePath();c.fillStyle=color;c.fill();c.strokeStyle=P.ink;c.lineWidth=1.6;c.lineJoin='round';c.stroke()}
export function leaf(c,x,y,size,angle=0,color=P.leaf){c.save();c.translate(x,y);c.rotate(angle);c.beginPath();c.moveTo(0,0);c.bezierCurveTo(-size,-size*.65,-size*.3,-size*1.25,0,-size*1.5);c.bezierCurveTo(size*.9,-size,size*.7,-size*.4,0,0);c.fillStyle=color;c.fill();c.strokeStyle=P.dark;c.lineWidth=1.2;c.stroke();line(c,[[0,0],[0,-size]],P.light,.8);c.restore()}
export function face(c,x,y,{blink=1,tired=0,angry=false}={}){for(const side of [-1,1]){oval(c,x+side*5,y,3.4,4*blink,P.cream);oval(c,x+side*5+.6,y+.3,1.5,2*blink,P.ink,false);if(angry||tired)line(c,[[x+side*2,y-5+tired*2],[x+side*8,y-6-tired]],P.ink,2)}c.beginPath();c.moveTo(x-3,y+7);c.quadraticCurveTo(x,y+(tired?4:10),x+4,y+6);c.strokeStyle=P.ink;c.lineWidth=1.5;c.stroke()}
export function shadow(c,x,y,r=16,altitude=0){oval(c,x,y,r*(1-altitude*.003),r*.29,P.shadow,false)}
export function star(c,x,y,r,color=P.critical,rotation=0){c.save();c.translate(x,y);c.rotate(rotation);const points=[];for(let i=0;i<8;i++){const a=i*Math.PI/4,s=i%2?r*.3:r;points.push([Math.cos(a)*s,Math.sin(a)*s])}shape(c,points,color);c.restore()}
export function healthBar(c,x,y,w,ratio,color){c.save();c.globalAlpha=.9;c.fillStyle=P.ink;c.beginPath();c.roundRect(x-w/2,y,w,5,3);c.fill();c.fillStyle=color;c.beginPath();c.roundRect(x-w/2+1,y+1,Math.max(0,(w-2)*ratio),3,2);c.fill();c.restore()}
